package net.civeira.phylax.features.access.userwebauthncredential.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DeviceNameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property device name of user webauthn credential ")
  void test_device_name_v_o_builder() {
    Assertions.assertFalse(DeviceNameVO.nullValue().getDeviceName().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(DeviceNameVO.tryFrom(null).getDeviceName().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", DeviceNameVO.from("one").getDeviceName().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> DeviceNameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", DeviceNameVO.from("one").toString());
  }
}
